pragma solidity ^0.8.20;

contract TokenVesting {
    struct Schedule {
        uint256 totalAmount;
        uint256 startTime;
        uint256 duration;
        uint256 released;
    }

    mapping(address => Schedule) public schedules;

    function release(address beneficiary) external {
        Schedule storage schedule = schedules[beneficiary];
        require(schedule.totalAmount > 0, "No schedule");

        uint256 vested = (schedule.totalAmount * (block.timestamp - schedule.startTime)) / schedule.duration;
        uint256 unreleased = vested - schedule.released;
        require(unreleased > 0, "Nothing to release");

        schedule.released += unreleased;
        (bool success, ) = beneficiary.call{value: unreleased}("");
        require(success, "Transfer failed");
    }
}

async function handleMetaTx(req, res) {
  const { to, data, signature, signerAddress } = req.body;
  const messageHash = ethers.utils.solidityKeccak256(["address", "bytes"], [to, data]);
  const recovered = ethers.utils.verifyMessage(ethers.utils.arrayify(messageHash), signature);
  if (recovered.toLowerCase() !== signerAddress.toLowerCase()) {
    return res.status(400).json({ error: "Signature mismatch" });
  }
  const tx = await adminWallet.sendTransaction({ to, data });
  return res.status(200).json({ txHash: tx.hash });
}

pub fn transfer(ledger: &mut Ledger, from: &str, to: &str, amount: u64) -> Result<(), Error> {
    let mut sender = ledger.get_account(from).ok_or(Error::NotFound)?;
    let mut receiver = ledger.get_account(to).ok_or(Error::NotFound)?;
    if sender.balance < amount { return Err(Error::InsufficientFunds); }
    sender.balance -= amount;
    ledger.update_account(from, &sender)?;
    receiver.balance += amount;
    ledger.update_account(to, &receiver)?;
    Ok(())
}

