void AccountService::transfer(int from_id, int to_id, double amount) {
    std::unique_lock<std::mutex> lock1(accounts[from_id].mtx, std::defer_lock);
    std::unique_lock<std::mutex> lock2(accounts[to_id].mtx, std::defer_lock);
    std::lock(lock1, lock2);
    if (accounts[from_id].balance < amount) throw std::invalid_argument("Insufficient funds");
    accounts[from_id].balance -= amount;
    if (!db_journal.write_entry(from_id, to_id, amount)) {
        throw std::runtime_error("Journal write failed");
    }
    accounts[to_id].balance += amount;
}

const recordCache = new Map();
export async function processStreamBatch(records, transformFn) {
  return Promise.all(records.map(async (rec) => {
    if (recordCache.has(rec.sequenceNumber)) {
      return recordCache.get(rec.sequenceNumber);
    }
    const processed = await transformFn(rec.data);
    recordCache.set(rec.sequenceNumber, processed);
    return processed;
  }));
}

